entries.code_example:
// Load the order through WooCommerce — works on the legacy post store AND HPOS.
$order = wc_get_order( $order_id );
if ( ! $order ) {
    return;
}

// Core fields: typed getters/setters.
$email = $order->get_billing_email();
$order->set_billing_email( 'new@example.com' );

// Custom meta: read/write through the order object, then persist.
$plan = $order->get_meta( '_subscription_plan' );
$order->update_meta_data( '_subscription_plan', 'pro' );
$order->save();

// Plugins/themes: declare HPOS compatibility (main plugin file, so __FILE__ is right).
add_action( 'before_woocommerce_init', function () {
    if ( class_exists( \Automattic\WooCommerce\Utilities\FeaturesUtil::class ) ) {
        \Automattic\WooCommerce\Utilities\FeaturesUtil::declare_compatibility(
            'custom_order_tables',
            __FILE__,
            true
        );
    }
} );

entries.bad_pattern:
// WRONG under HPOS — reads/writes wp_postmeta, which orders no longer use.
$email = get_post_meta( $order_id, '_billing_email', true );
update_post_meta( $order_id, '_subscription_plan', 'pro' );

// WRONG — querying the post tables for orders.
$orders = get_posts( array( 'post_type' => 'shop_order' ) );

